// tests/unit/sleep-utils.test.ts
import { describe, it, expect } from "vitest";

// Export these from route.ts or extract to lib/sleep-utils.ts
import { parseDuration, timeToDate } from "@/lib/sleep-utils";

describe("parseDuration", () => {
  it("same-day: 22:00 → 06:00 = 8h", () => {
    expect(parseDuration("22:00", "06:00")).toBe(8.0);
  });
  it("same-day non-overnight: 08:00 → 09:30 = 1.5h", () => {
    expect(parseDuration("08:00", "09:30")).toBe(1.5);
  });
  it("midnight edge: 23:59 → 00:01 = 0.03h", () => {
    expect(parseDuration("23:59", "00:01")).toBeCloseTo(0.03, 1);
  });
  it("identical times = 0h (not 24h)", () => {
    expect(parseDuration("08:00", "08:00")).toBe(0);
  });
});

describe("timeToDate", () => {
  it("returns epoch date with correct hours/minutes", () => {
    const d = timeToDate("14:30");
    expect(d.getHours()).toBe(14);
    expect(d.getMinutes()).toBe(30);
    expect(d.getFullYear()).toBe(1970);
  });
});
```

**Edge cases missing:** midnight crossing with `wake < bed` is only handled via `1440 - bed + wake` — not tested. Identical times return 0 but could confuse callers.

