  it("maps 'Solde' → 'solde'", () => expect(normalizeHeader("Solde")).toBe("solde"));
  it("maps 'Montant' → 'montant'", () => expect(normalizeHeader("Montant")).toBe("montant"));
});

describe("parseDate", () => {
  it("DD/MM/YYYY format", () => {
    expect(parseDate("04/06/2026")?.toISOString()).toBe("2026-06-04T00:00:00.000Z");
  });
  it("DD-MM-YYYY format", () => {
    expect(parseDate("04-06-2026")?.toISOString()).toBe("2026-06-04T00:00:00.000Z");
  });
  it("YYYY-MM-DD ISO format", () => {
    expect(parseDate("2026-06-04")?.toISOString()).toBe("2026-06-04T00:00:00.000Z");
  });
  it("invalid date returns null", () => {
    expect(parseDate("not-a-date")).toBeNull();
    expect(parseDate("32/13/2026")).toBeNull();
  });
});
