import { describe, it, expect, vi, beforeEach } from "vitest";
import { GET, POST } from "@/app/api/tasks/route";
import { prisma } from "@/lib/prisma";
import { NextRequest } from "next/server";

vi.mock("@/lib/prisma", () => ({
  prisma: { task: { findMany: vi.fn(), create: vi.fn() } },
}));

describe("GET /api/tasks", () => {
  it("returns all tasks without scope filter", async () => {
    vi.mocked(prisma.task.findMany).mockResolvedValue([]);
    const req = new NextRequest("http://localhost/api/tasks");
    const res = await GET(req);
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual([]);
  });

  it("passes scope filter to prisma", async () => {
    vi.mocked(prisma.task.findMany).mockResolvedValue([]);
    const req = new NextRequest("http://localhost/api/tasks?scope=DAY");
    await GET(req);
    expect(prisma.task.findMany).toHaveBeenCalledWith(
      expect.objectContaining({ where: { scope: "DAY" } })
    );
  });

  it("returns 500 on prisma error", async () => {
    vi.mocked(prisma.task.findMany).mockRejectedValue(new Error("DB error"));
    const req = new NextRequest("http://localhost/api/tasks");
    const res = await GET(req);
    expect(res.status).toBe(500);
  });
});

describe("POST /api/tasks", () => {
  it("returns 400 on empty title", async () => {
    const req = new NextRequest("http://localhost/api/tasks", {
      method: "POST",
      body: JSON.stringify({ title: "", scope: "DAY" }),
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it("returns 400 on invalid scope", async () => {
    const req = new NextRequest("http://localhost/api/tasks", {
      method: "POST",
      body: JSON.stringify({ title: "Test", scope: "INVALID" }),
    });
    const res = await POST(req);
    expect(res.status).toBe(400);
  });

  it("creates task with optional dueDate", async () => {
    const mockTask = { id: "1", title: "Test", scope: "DAY", priority: "MEDIUM",
      completed: false, dueDate: new Date("2026-06-10"), completedAt: null, createdAt: new Date() };
    vi.mocked(prisma.task.create).mockResolvedValue(mockTask as any);
    const req = new NextRequest("http://localhost/api/tasks", {
      method: "POST",
      body: JSON.stringify({ title: "Test", scope: "DAY", dueDate: "2026-06-10" }),
    });
    const res = await POST(req);
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.dueDate).toBe("2026-06-10");
  });
});
