`POST /api/finance` checks `body.action === "upsert_investment"` before falling back to snapshot parsing — if an invalid `action` string is sent with snapshot fields, it falls through to snapshot parsing silently.

```ts
describe("POST /api/finance — unknown action falls through to snapshot", () => {
  it("treats unknown action string as snapshot attempt", async () => {
    const req = new NextRequest("http://localhost/api/finance", {
      method: "POST",
      body: JSON.stringify({ action: "delete_investment", date: "2026-06-04",
        bankBalance: 1000, totalInvested: 500, totalValue: 600 }),
    });
    const res = await POST(req);
    // Falls through and creates a snapshot — may not be intended behavior
    expect([200, 400]).toContain(res.status);
  });
});
